use super::NormalMode;
use baozi_core::__scene_integration::integration::SceneGeometrySelectionEvidence;
use baozi_core::PrimitiveId;

/// Published normal-generation effects, retained independently of the Scene owner.
pub struct NormalGenerationReport {
    preparation: crate::GeometryPreparationReport,
}

impl NormalGenerationReport {
    /// Complete actual field effects, including a Tangent generated by the explicit policy.
    pub const fn preparation(&self) -> &crate::GeometryPreparationReport {
        &self.preparation
    }
    pub fn output_tangent_attribute_index(&self) -> Option<u32> {
        self.preparation
            .evidence
            .target(0)
            .expect("published normal target")
            .tangent_attribute_index()
    }

    pub(crate) const fn selected(evidence: SceneGeometrySelectionEvidence) -> Self {
        Self {
            preparation: crate::GeometryPreparationReport::new(evidence),
        }
    }
    /// Input target whose Vertex, Corner, and Face identities are preserved.
    pub fn input_target(&self) -> PrimitiveId {
        self.preparation
            .evidence
            .target(0)
            .expect("published normal target")
            .input_target()
    }
    /// The target primitive in the new generation.
    pub fn output_target(&self) -> PrimitiveId {
        self.preparation
            .evidence
            .target(0)
            .expect("published normal target")
            .output_target()
    }
    /// The normal algorithm applied to this primitive.
    pub fn mode(&self) -> NormalMode {
        if self
            .preparation
            .evidence
            .target(0)
            .expect("published normal target")
            .smooth()
        {
            NormalMode::Smooth
        } else {
            NormalMode::Flat
        }
    }
    /// Whether replacing authored NORMAL values was explicitly authorized and applied.
    pub fn replaced_authored_normals(&self) -> bool {
        self.preparation
            .evidence
            .target(0)
            .expect("published normal target")
            .replaced_normal()
    }
    /// Whether deleting an invalidated TANGENT field was explicitly authorized and applied.
    pub fn removed_tangents(&self) -> bool {
        self.preparation
            .evidence
            .target(0)
            .expect("published normal target")
            .removed_tangent()
    }
    /// Number of owner-local metadata entries removed with the deleted TANGENT field.
    pub fn removed_metadata_entries(&self) -> u32 {
        self.preparation.evidence.removed_metadata_entries()
    }
    /// The generated field's index in the Scene-wide attribute table.
    pub fn output_normal_attribute_index(&self) -> u32 {
        self.preparation
            .evidence
            .target(0)
            .expect("published normal target")
            .normal_attribute_index()
            .expect("published normal")
    }
}

impl std::fmt::Debug for NormalGenerationReport {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("NormalGenerationReport")
            .field("input_target", &self.input_target())
            .field("output_target", &self.output_target())
            .field("mode", &self.mode())
            .field(
                "replaced_authored_normals",
                &self.replaced_authored_normals(),
            )
            .field("removed_tangents", &self.removed_tangents())
            .field("removed_metadata_entries", &self.removed_metadata_entries())
            .finish()
    }
}
